old='''if(message.type==="BC_MODULE_TEST"){(async()=>{try{const kind=String(message.module||""),token=String(message.token||"").trim();if(!token)throw new Error("Token пустой");if(kind==="figma"){const r=await fetch("https://api.figma.com/v1/me",{headers:{"X-Figma-Token":token}}),raw=await r.text();if(!r.ok)throw new Error(`Figma HTTP ${r.status}: ${raw.slice(0,180)}`);const d=JSON.parse(raw);sendResponse({ok:true,name:d.handle||d.email||"Figma"});return}if(kind==="github"){const r=await fetch("https://api.github.com/user",{headers:{Authorization:`Bearer ${token}`,Accept:"application/vnd.github+json","X-GitHub-Api-Version":"2022-11-28"}}),raw=await r.text();if(!r.ok)throw new Error(`GitHub HTTP ${r.status}: ${raw.slice(0,180)}`);const d=JSON.parse(raw);sendResponse({ok:true,name:d.login||d.name||"GitHub"});return}if(kind==="gemini"){const r=await fetch("https://generativelanguage.googleapis.com/v1beta/models?key="+encodeURIComponent(token)),raw=await r.text();if(!r.ok)throw new Error(`Gemini HTTP ${r.status}: ${raw.slice(0,180)}`);sendResponse({ok:true,name:"Google AI · Gemini"});return}throw new Error("Unsupported module") }catch(e){sendResponse({ok:false,error:e?.message||String(e)})}})();return true;}'''
new='''if(message.type==="BC_MODULE_TEST"){(async()=>{try{const kind=String(message.module||""),token=String(message.token||"").trim();if(!token)throw new Error("Token пустой");if(kind==="figma"){const r=await fetch("https://api.figma.com/v1/me",{headers:{"X-Figma-Token":token}}),raw=await r.text();if(!r.ok)throw new Error(`Figma HTTP ${r.status}: ${raw.slice(0,180)}`);const d=JSON.parse(raw);sendResponse({ok:true,name:d.handle||d.email||"Figma"});return}if(kind==="github"){const headers={Authorization:`Bearer ${token}`,Accept:"application/vnd.github+json","X-GitHub-Api-Version":"2022-11-28"},request=async url=>{const r=await fetch(url,{headers}),raw=await r.text();let data=null;try{data=raw?JSON.parse(raw):null}catch{data=raw}return{ok:r.ok,status:r.status,data,raw}};const user=await request("https://api.github.com/user");if(!user.ok)throw new Error(`GitHub account HTTP ${user.status}: ${typeof user.data==="string"?user.data.slice(0,180):user.data?.message||user.raw.slice(0,180)}`);const repos=["jeep-jim/OSMINOG","jeep-jim/OSMINOG-Releases"],checks=[];for(const repo of repos){const rr=await request(`https://api.github.com/repos/${repo}`);if(rr.status===404){checks.push({repo,visible:false,write:false,status:404});continue}if(!rr.ok)throw new Error(`GitHub ${repo} HTTP ${rr.status}: ${typeof rr.data==="string"?rr.data.slice(0,180):rr.data?.message||rr.raw.slice(0,180)}`);const p=rr.data?.permissions||{},write=!!(p.admin||p.maintain||p.push);checks.push({repo,visible:true,write,status:rr.status,permissions:p,private:!!rr.data?.private})}const missing=checks.filter(x=>!x.visible),readonly=checks.filter(x=>x.visible&&!x.write),ownerOk=!missing.length&&!readonly.length;if(!ownerOk){const code=missing.length?"repo_access":"repo_write",detail=missing.length?`Токен GitHub работает, но не видит: ${missing.map(x=>x.repo).join(", ")}. В fine-grained token открой Repository access → Only select repositories и добавь OSMINOG + OSMINOG-Releases.`:`Токен видит репозитории, но не имеет записи: ${readonly.map(x=>x.repo).join(", ")}. Нужен Contents: Read and write.`;sendResponse({ok:false,accountOk:true,name:user.data?.login||user.data?.name||"GitHub",code,error:detail,owner:{ok:false,checks}});return}sendResponse({ok:true,accountOk:true,name:user.data?.login||user.data?.name||"GitHub",owner:{ok:true,checks,repositories:repos}});return}if(kind==="gemini"){const r=await fetch("https://generativelanguage.googleapis.com/v1beta/models?key="+encodeURIComponent(token)),raw=await r.text();if(!r.ok)throw new Error(`Gemini HTTP ${r.status}: ${raw.slice(0,180)}`);sendResponse({ok:true,name:"Google AI · Gemini"});return}throw new Error("Unsupported module") }catch(e){sendResponse({ok:false,error:e?.message||String(e)})}})();return true;}'''
