replacement='''  async function verifyOwner(options={}){const allowCached=options.allowCached!==false,got=await ownerStorage(),mods=got[MODULE_KEY]||{},github=mods.github||{},token=String(github.token||"").trim(),grant=got[OWNER_GRANT_KEY]||{},freshGrant=!!(grant.verified===true&&grant.ownerMax===true&&Date.now()-Number(grant.verifiedAt||0)>=0&&Date.now()-Number(grant.verifiedAt||0)<OWNER_GRANT_TTL);if(!token){globalThis.OSMINOGOwnerVerified=false;ownerStatus={ok:false,cached:false,reason:"token",user:""};return ownerStatus}try{const statuses=[];for(const repo of [OWNER_REPO,OWNER_RELEASE_REPO]){const st=await globalThis.BriefCraftBridge?.executeTool?.("github_status",{repo});if(!st||st.error||st.ok===false){const msg=String(st?.error||"GitHub API не ответил");if(/404|not found/i.test(msg)){globalThis.OSMINOGOwnerVerified=false;ownerStatus={ok:false,cached:false,reason:"repo_access",repo,user:github.name||""};return ownerStatus}throw new Error(msg)}const perms=st.permissions||{},write=!!(perms.admin||perms.maintain||perms.push);if(!write){globalThis.OSMINOGOwnerVerified=false;ownerStatus={ok:false,cached:false,reason:"repo_write",repo,user:st.user||github.name||""};return ownerStatus}statuses.push(st)}const nextGrant={verified:true,ownerMax:true,repo:OWNER_REPO,repos:[OWNER_REPO,OWNER_RELEASE_REPO],user:statuses[0]?.user||github.name||"GitHub",verifiedAt:Date.now()};await chrome.storage.local.set({[OWNER_GRANT_KEY]:nextGrant});globalThis.OSMINOGOwnerVerified=true;ownerStatus={ok:true,cached:false,reason:"",user:nextGrant.user};return ownerStatus}catch(error){if(allowCached&&freshGrant){globalThis.OSMINOGOwnerVerified=true;ownerStatus={ok:true,cached:true,reason:error?.message||String(error),user:grant.user||github.name||"GitHub"};return ownerStatus}globalThis.OSMINOGOwnerVerified=false;ownerStatus={ok:false,cached:false,reason:error?.message||String(error),user:github.name||""};return ownerStatus}}
  async function connectOwnerToken(){const input=$("[data-owner-token]",el),button=$("[data-owner-token-save]",el),out=$("[data-poseidon-state]",el),token=String(input?.value||"").trim();if(!token||!button)return;button.disabled=true;if(out)out.textContent="Проверяю GitHub аккаунт и оба репозитория…";try{const test=await chrome.runtime.sendMessage({type:"BC_MODULE_TEST",module:"github",token});if(!test?.ok)throw new Error(test?.error||"GitHub token не принят");if(!test.owner?.ok)throw new Error("GitHub аккаунт подтверждён, но Owner Max не подтверждён");const got=await ownerStorage(),mods=got[MODULE_KEY]||{},grant={verified:true,ownerMax:true,repo:OWNER_REPO,repos:test.owner.repositories||[OWNER_REPO,OWNER_RELEASE_REPO],user:test.name||"GitHub",verifiedAt:Date.now()};mods.github={connected:true,token,name:test.name||"GitHub",ownerVerified:true,at:Date.now()};await chrome.storage.local.set({[MODULE_KEY]:mods,[OWNER_GRANT_KEY]:grant});globalThis.OSMINOGOwnerVerified=true;ownerStatus={ok:true,cached:false,reason:"",user:grant.user};input.value="";await refreshPoseidon();document.dispatchEvent(new CustomEvent("osminog:owner-status",{detail:{verified:true,user:grant.user}}))}catch(error){if(out)out.textContent=error?.message||String(error)}finally{button.disabled=false}}
  async function openOwnerGitHub'''
